// Domain 3 — Kubernetes (LPI 703.1-703.3). Original flashcards for LPI DevOps Tools Engineer 701-200 v2.0.
let n = 0;
const c = (topic, front, back) => ({ id: `d3-f${String(++n).padStart(3, '0')}`, topic, front, back });

export default [
  c('3.1', 'Control plane components?', '`kube-apiserver`, `etcd`, `kube-scheduler`, `kube-controller-manager` (plus `cloud-controller-manager` in cloud setups).'),
  c('3.1', 'Node components?', '`kubelet` (runs Pod containers), `kube-proxy` (Service rules), a CRI container runtime (containerd, CRI-O).'),
  c('3.1', 'Who talks to etcd?', 'Only the API server. Everything else (kubectl, scheduler, controllers, kubelets) goes through the API server.'),
  c('3.1', 'Scheduler vs kubelet?', 'Scheduler chooses the node for an unscheduled Pod. Kubelet on that node starts the containers.'),
  c('3.1', 'Default kubeconfig and overrides?', '`~/.kube/config`; override with `KUBECONFIG` (colon-separated list, merged) or `--kubeconfig`.'),
  c('3.1', 'What is a kubeconfig context?', 'A named combination of cluster, user and optional default namespace; `current-context` selects the active one.'),
  c('3.1', 'kubectl config subcommands?', '`get-contexts` list, `current-context` print, `use-context NAME` switch, `set-context --current --namespace=dev` change namespace, `view` show merged config.'),
  c('3.1', 'apiVersion cheat list?', '`v1`: Pod, Service, ConfigMap, Secret, PVC. `apps/v1`: Deployment, ReplicaSet, StatefulSet, DaemonSet. `batch/v1`: Job, CronJob. `networking.k8s.io/v1`: Ingress.'),
  c('3.1', '`kubectl describe` vs `get`?', '`get` prints a table (or `-o yaml/json/wide`); `describe` shows detail plus Events, the first stop for scheduling and image-pull problems.'),
  c('3.1', 'Which `kubectl logs` flags matter?', '`-f` follow, `--tail N`, `--previous` (last crashed instance), `-c NAME` container, `-l selector`.'),
  c('3.1', '`kubectl exec` syntax?', '`kubectl exec -it POD [-c CONTAINER] -- sh`; `--` separates kubectl flags from the command.'),
  c('3.1', '`kubectl create` vs `apply`?', '`create -f` fails with AlreadyExists if the object exists. `apply -f` creates or updates declaratively and is repeatable.'),
  c('3.1', 'What does `kubectl run` create?', 'Only a Pod (since 1.18). A Deployment needs `kubectl create deployment`.'),
  c('3.1', 'What are `expose`, `scale`, `set image`, `edit`?', '`expose` creates a Service; `scale --replicas=N` sets replicas; `set image DEP CONTAINER=IMAGE` starts a rolling update; `edit` changes the live object in `$EDITOR`.'),
  c('3.1', 'What is `kubectl explain` for?', 'Built-in API schema docs, e.g. `kubectl explain deployment.spec.strategy`; add `--recursive` for the full tree.'),
  c('3.1', 'What is a Kubernetes Operator?', 'CustomResourceDefinition plus a custom controller that automates deploying and operating an application.'),
  c('3.2', 'Four top-level manifest fields?', '`apiVersion`, `kind`, `metadata`, `spec` (`status` is written by the cluster).'),
  c('3.2', 'What is a Pod?', 'Smallest deployable unit: one or more containers sharing network namespace (one IP) and volumes. Ephemeral; use controllers.'),
  c('3.2', 'Deployment selector rule?', '`spec.selector.matchLabels` must match `spec.template.metadata.labels`; the selector is immutable.'),
  c('3.2', 'Rolling update defaults?', 'Strategy `RollingUpdate`, `maxSurge` 25% (rounds up), `maxUnavailable` 25% (rounds down). Alternative: `Recreate`.'),
  c('3.2', 'Rollout commands?', '`kubectl rollout status|history|undo|restart|pause|resume deployment/NAME`; `undo --to-revision=N`.'),
  c('3.2', 'Requests vs limits?', 'Requests are what the scheduler reserves; limits are enforced ceilings (memory over limit = OOM kill, CPU is throttled).'),
  c('3.2', 'Readiness vs liveness probe?', 'Readiness failure removes the Pod from Service endpoints; liveness failure makes the kubelet restart the container.'),
  c('3.2', 'Service types?', 'ClusterIP (default), NodePort (30000-32767), LoadBalancer (needs provider), ExternalName (CNAME, no selector); headless = `clusterIP: None`.'),
  c('3.2', '`port` vs `targetPort` vs `nodePort`?', 'Service port / container port on the Pods / port opened on every node.'),
  c('3.2', 'Ingress requirements?', '`networking.k8s.io/v1`; routes HTTP(S) by host/path to Services; does nothing without an Ingress controller; `ingressClassName` picks it.'),
  c('3.2', 'PVC access modes?', 'RWO ReadWriteOnce (one node), ROX ReadOnlyMany, RWX ReadWriteMany, RWOP ReadWriteOncePod (one Pod).'),
  c('3.2', 'PV vs PVC vs StorageClass?', 'PV = storage (cluster-scoped); PVC = namespaced request; StorageClass = template for dynamic provisioning.'),
  c('3.2', 'ConfigMap vs Secret?', 'ConfigMap: plain config. Secret: sensitive data, base64-encoded in `data` (plain in `stringData`), NOT encrypted by default.'),
  c('3.2', 'How are ConfigMaps used in a Pod?', 'Env vars via `valueFrom.configMapKeyRef` or `envFrom`, or mounted as files. Env vars need a restart to update.'),
  c('3.2', 'DaemonSet, StatefulSet, Job, CronJob?', 'Pod per node; stable names and per-Pod PVCs; run to completion (`OnFailure`/`Never`); Job on a cron `schedule`.'),
  c('3.3', 'Chart, release, values?', 'Chart = package; release = installed instance with revisions; values = configuration (`values.yaml` defaults).'),
  c('3.3', 'Helm lifecycle commands?', '`helm install NAME CHART`, `list`, `upgrade`, `history`, `rollback NAME REV`, `uninstall NAME`.'),
  c('3.3', 'Idempotent Helm deploy?', '`helm upgrade --install NAME CHART -f values.yaml`.'),
  c('3.3', 'Helm value precedence?', 'Chart `values.yaml` < `-f` files (left to right) < `--set`.'),
  c('3.3', 'Kustomize vs Helm?', 'Kustomize patches plain YAML with overlays, no templates, no release tracking. Helm templates charts and tracks releases. Apply with `kubectl apply -k DIR`.'),
  c('3.3', 'GitOps with Flux CD or Argo CD?', 'In-cluster controllers pull desired state from Git and reconcile it, correcting drift. Flux: `Kustomization`, `HelmRelease`. Argo CD: `Application`.'),
];
